use std::fs;

fn scan_network() {
    let mut ports = vec![];
    let mut files = vec![];

    // Scan for open ports
    for port in 1..1025 {
        let result = match std::process::Command::new("nmap")
            .arg("-p")
            .arg(port)
            .arg("192.168.1.1")
            .output() {
            Ok(output) => {
                if output.status.success() {
                    let output_str = String::from_utf8(output.stdout).unwrap();
                    if output_str.contains("open") {
                        ports.push(port);
                    }
                }
            },
            Err(e) => eprintln!("Error scanning port {}: {}", port, e),
        };
    }

    // List files in the target directory
    let dir = "/var/www/html";
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();
        if path.is_file() {
            files.push(path.display().to_string());
        }
    }

    println!("Open ports: {:?}", ports);
    println!("Files in target directory: {:?}", files);
}
